use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node may reach. Must match the HTTPClient allowlist in the graph.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Upper bound on subscriptions fetched in one run.
const MAX_URLS: usize = 64;

struct Node;

/// Returns the lowercase host of an `https://` URL that has no userinfo and no
/// port, or `None` if the URL does not have that shape.
fn host_of(url: &str) -> Option<String> {
    if url.chars().any(|c| c.is_control() || c == ' ') {
        return None;
    }
    let rest = url.strip_prefix("https://")?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() || authority.contains('@') || authority.contains(':') {
        return None;
    }
    Some(authority.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for (i, url) in subscriptions.urls.into_iter().enumerate() {
            if i >= MAX_URLS {
                failures.push(FetchFailure {
                    url,
                    error: format!("over the limit of {MAX_URLS} subscriptions"),
                });
                continue;
            }

            // Pre-check the host so an out-of-scope URL becomes a recorded
            // failure instead of a trap at the boundary, which would abort the run.
            let allowed = host_of(&url).is_some_and(|h| ALLOWED_HOSTS.contains(&h.as_str()));
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
